shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --burgundy: #7a261f;
    --serif-en: 'Playfair Display', Georgia, serif;
    --body-en: 'Lora', Georgia, serif;
    --serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  /* Strict Language Toggle Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--serif-cn);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--body-en);
    line-height: 1.78;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1160px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }

  .brand-logo {
    font-family: var(--serif-en);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }

  .brand-kicker {
    font-family: var(--mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.32rem 0.75rem;
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Essay Header */
  .essay-hero {
    max-width: 960px;
    margin: 0 auto;
    padding: 4.5rem 1.5rem 3rem;
    text-align: center;
    border-bottom: 1px solid var(--line);
    position: relative;
  }

  .hero-ornament {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
  }

  .hero-ornament::before,
  .hero-ornament::after {
    content: "";
    width: 48px;
    height: 1px;
    background: var(--accent);
  }

  .hero-rubric {
    font-family: var(--mono);
    font-size: 0.75rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
  }

  .essay-title {
    font-family: var(--serif-cn);
    font-weight: 700;
    font-size: clamp(2.25rem, 4.8vw, 3.65rem);
    line-height: 1.22;
    color: var(--ink);
    margin-bottom: 1.35rem;
    letter-spacing: -0.01em;
  }

  :host([lang="en"]) .essay-title {
    font-family: var(--serif-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .essay-dek {
    max-width: 680px;
    margin: 0 auto 2rem;
    font-size: 1.15rem;
    line-height: 1.75;
    color: var(--muted);
    font-weight: 400;
  }

  :host([lang="en"]) .essay-dek {
    font-family: var(--body-en);
    font-style: italic;
    font-size: 1.22rem;
  }

  .byline-bar {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 0.75rem 1.5rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--sans);
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-author {
    color: var(--ink);
    font-weight: 600;
    letter-spacing: 0.03em;
  }

  .byline-dot {
    color: var(--accent);
  }

  /* Main Essay Container */
  .essay-container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 1.5rem 5rem;
  }

  /* Opening Scene: Orangeburg Sermon */
  .opening-scene {
    max-width: 740px;
    margin: 3.25rem auto 3.5rem;
    padding: 2.5rem 2.75rem;
    background: linear-gradient(180deg, var(--paper-card) 0%, rgba(243, 239, 230, 0.45) 100%);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    position: relative;
  }

  .scene-dateline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
    padding-bottom: 1.25rem;
    margin-bottom: 1.75rem;
    border-bottom: 1px dashed var(--line-strong);
    font-family: var(--mono);
    font-size: 0.74rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--muted);
  }

  .scene-dateline strong {
    color: var(--accent);
    font-weight: 700;
  }

  /* Prose Paragraphs */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.55rem;
    letter-spacing: 0.01em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.14rem;
  }

  .prose-lead {
    font-size: 1.24rem;
    line-height: 1.9;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
  }

  :host([lang="en"]) .prose-lead {
    font-size: 1.26rem;
    line-height: 1.78;
    font-weight: 400;
  }

  /* Pulpit Proclamation Highlight (p2) */
  .pulpit-proclamation {
    margin: 2rem 0;
    padding: 1.65rem 1.75rem;
    background: var(--paper);
    border-left: 4px solid var(--burgundy);
    border-top: 1px solid var(--line);
    border-right: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
  }

  .pulpit-proclamation .prose-p {
    margin-bottom: 0;
    font-size: 1.35rem;
    line-height: 1.6;
    font-weight: 700;
    color: var(--ink);
  }

  :host([lang="en"]) .pulpit-proclamation .prose-p {
    font-family: var(--serif-en);
    font-size: 1.45rem;
  }

  /* Chapter Dividers */
  .chapter-break {
    max-width: 740px;
    margin: 4rem auto 2.5rem;
    text-align: center;
    position: relative;
  }

  .chapter-numeral {
    display: inline-block;
    font-family: var(--serif-en);
    font-style: italic;
    font-size: 0.95rem;
    color: var(--accent);
    letter-spacing: 0.14em;
    padding: 0 1rem;
    background: var(--paper);
    position: relative;
    z-index: 2;
  }

  .chapter-break::before {
    content: "";
    position: absolute;
    top: 11px;
    left: 15%;
    right: 15%;
    height: 1px;
    background: var(--line-strong);
    z-index: 1;
  }

  .chapter-title {
    margin-top: 0.55rem;
    font-family: var(--serif-cn);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
  }

  :host([lang="en"]) .chapter-title {
    font-family: var(--serif-en);
    font-size: 1.65rem;
  }

  .chapter-sub {
    margin-top: 0.3rem;
    font-family: var(--sans);
    font-size: 0.84rem;
    color: var(--muted);
  }

  /* Asymmetric Editorial Grid for Chapters */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) 320px;
    gap: 3.25rem;
    justify-content: center;
    align-items: start;
    margin: 0 auto;
  }

  .narrative-col {
    min-width: 0;
  }

  .marginalia-rail {
    position: sticky;
    top: 4.75rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Ecclesiastical Dossier Card (May - Oct 2026) */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.4rem 1.35rem;
  }

  .dossier-header {
    font-family: var(--mono);
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 700;
    padding-bottom: 0.65rem;
    margin-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .dossier-timeline {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .dossier-item {
    position: relative;
    padding-left: 0.9rem;
    border-left: 2px solid var(--accent);
  }

  .dossier-date {
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--ink);
    text-transform: uppercase;
  }

  .dossier-desc {
    font-family: var(--sans);
    font-size: 0.84rem;
    line-height: 1.55;
    color: var(--body);
    margin-top: 0.15rem;
  }

  /* Verified Pull Quote Callout (data-derive="q1") */
  .pull-quote {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.65rem 1.5rem;
    border-top: 3px solid var(--accent);
    position: relative;
  }

  .pull-quote::before {
    content: "“";
    font-family: var(--serif-en);
    font-size: 3.5rem;
    line-height: 1;
    color: var(--accent);
    opacity: 0.55;
    display: block;
    margin-bottom: -0.75rem;
  }

  .pull-quote .quote-text {
    font-family: var(--serif-cn);
    font-size: 1.05rem;
    line-height: 1.75;
    color: #f7f4ed;
    margin-bottom: 0.95rem;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--body-en);
    font-style: italic;
  }

  .pull-quote .quote-attrib {
    font-family: var(--mono);
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    color: #b9b2a3;
    text-transform: uppercase;
  }

  /* Dual Whirlwind Ledger (inline analytical contrast next to p9-p10) */
  .whirlwind-panel {
    margin: 2rem 0 2.25rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem 1.5rem;
  }

  .whirlwind-title {
    font-family: var(--mono);
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--muted);
    margin-bottom: 0.95rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .whirlwind-cols {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
  }

  .whirlwind-col {
    padding: 0.85rem 1rem;
    background: var(--paper);
    border: 1px solid var(--line);
  }

  .whirlwind-col.promise {
    border-top: 3px solid #2b6cb0;
  }

  .whirlwind-col.peril {
    border-top: 3px solid var(--burgundy);
  }

  .whirlwind-tag {
    font-family: var(--mono);
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 0.45rem;
  }

  .whirlwind-col.promise .whirlwind-tag { color: #2b6cb0; }
  .whirlwind-col.peril .whirlwind-tag { color: var(--burgundy); }

  .whirlwind-list {
    font-family: var(--sans);
    font-size: 0.86rem;
    line-height: 1.6;
    color: var(--body);
  }

  /* Bespoke Conceptual SVG Diagram Section */
  .triptych-figure {
    max-width: 920px;
    margin: 3.5rem auto;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 2rem 2rem 1.65rem;
  }

  .figure-kicker {
    font-family: var(--mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.35rem;
  }

  .figure-heading {
    font-family: var(--serif-cn);
    font-size: 1.32rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }

  :host([lang="en"]) .figure-heading {
    font-family: var(--serif-en);
  }

  .figure-sub {
    font-family: var(--sans);
    font-size: 0.86rem;
    color: var(--muted);
    margin-bottom: 1.35rem;
  }

  .svg-wrapper {
    width: 100%;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.5rem;
  }

  .svg-wrapper svg {
    display: block;
    width: 100%;
    height: auto;
  }

  /* Papal Encyclical Split Feature (p13.s1 & p13.s2) */
  .encyclical-monument {
    margin: 1.75rem 0 2.25rem;
    padding: 1.85rem 2rem;
    background: linear-gradient(135deg, #f5f0e5 0%, #ebe3d2 100%);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--accent);
    position: relative;
  }

  .encyclical-badge {
    font-family: var(--mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.65rem;
    display: block;
  }

  .encyclical-quote {
    font-size: 1.22rem;
    line-height: 1.78;
    font-weight: 600;
    color: var(--ink);
    margin: 0;
  }

  :host([lang="en"]) .encyclical-quote {
    font-family: var(--serif-en);
    font-weight: 700;
    font-size: 1.26rem;
    line-height: 1.62;
  }

  /* Centered Single-Column Literary Track for Chapter III & Coda */
  .single-track {
    max-width: 680px;
    margin: 0 auto;
  }

  /* Sam Altman Statement Card (p16) */
  .altman-dispatch {
    margin: 1.85rem 0 2.1rem;
    padding: 1.55rem 1.75rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
  }

  .dispatch-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-family: var(--mono);
    font-size: 0.72rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 0.75rem;
  }

  .altman-dispatch .prose-p {
    margin-bottom: 0;
    font-size: 1.14rem;
    color: var(--ink);
    font-weight: 600;
  }

  :host([lang="en"]) .altman-dispatch .prose-p {
    font-family: var(--body-en);
    font-style: italic;
    font-weight: 400;
  }

  /* Coda Box (p18 - p21) */
  .sermon-coda {
    max-width: 720px;
    margin: 3.5rem auto 2.5rem;
    padding: 2.5rem 2.75rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    position: relative;
  }

  .coda-closing-quote {
    margin-top: 1.5rem;
    padding-top: 1.35rem;
    border-top: 1px solid var(--line-strong);
  }

  .coda-closing-quote .prose-p {
    margin-bottom: 0;
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
  }

  :host([lang="en"]) .coda-closing-quote .prose-p {
    font-family: var(--serif-en);
    font-size: 1.3rem;
  }

  /* Archival Photo Caption Plate (p22) */
  .archival-caption-plate {
    max-width: 720px;
    margin: 2rem auto 0;
    padding: 1rem 1.25rem;
    background: var(--paper);
    border: 1px dashed var(--line-strong);
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
  }

  .caption-icon {
    font-family: var(--mono);
    font-size: 0.7rem;
    color: var(--accent);
    border: 1px solid var(--accent);
    padding: 0.15rem 0.4rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    flex-shrink: 0;
    margin-top: 0.2rem;
  }

  .archival-caption-plate .prose-p {
    margin-bottom: 0;
    font-family: var(--sans);
    font-size: 0.84rem;
    line-height: 1.6;
    color: var(--muted);
  }

  /* Footer */
  .essay-footer {
    border-top: 1px solid var(--line);
    padding: 2.5rem 1.5rem;
    text-align: center;
    font-family: var(--mono);
    font-size: 0.74rem;
    color: var(--muted);
    letter-spacing: 0.06em;
  }

  /* Responsive Mobile Reflow (<= 880px and 390px) */
  @media (max-width: 880px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .marginalia-rail {
      position: static;
    }
    .opening-scene,
    .sermon-coda {
      padding: 1.75rem 1.35rem;
    }
    .triptych-figure {
      padding: 1.35rem 1rem;
    }
  }

  @media (max-width: 540px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .essay-hero {
      padding: 2.75rem 1rem 2rem;
    }
    .essay-container {
      padding: 0 1rem 3.5rem;
    }
    .whirlwind-cols {
      grid-template-columns: 1fr;
    }
    .encyclical-monument {
      padding: 1.35rem 1.2rem;
    }
    .archival-caption-plate {
      flex-direction: column;
      gap: 0.5rem;
    }
  }
